+  /**
+   * Hand seed out of one packet, file its new card, and note what left.
+   * Nothing is written where the packet is absent or the request cannot be met.
+   */
+  handOut(name: string, seeds: number): Packet {
+    const packet = this.packetFor(name);
+    if (packet === NOT_IN_THE_STORE) {
+      throw new Error("nothing of that name in the store");
+    }
+    if (!Number.isInteger(seeds) || seeds <= 0) {
+      throw new Error("seed asked for must be a whole number above nought");
+    }
+    if (packet.seeds < seeds) {
+      throw new Error("the packet does not hold that many seeds");
+    }
+
+    const left = packet.holding(packet.seeds - seeds);
+    this.file(left);
+    const daybook = this.daybook();
+    const startsANewLine = existsSync(daybook) && !readFileSync(daybook, "utf8").endsWith("\n");
+    appendFileSync(daybook, `${startsANewLine ? "\n" : ""}${noted(name, seeds, left.seeds)}\n`, "utf8");
+    return left;
+  }
 }
